 return <div className="page anime-detail-page"><button className="detail-back" onClick={()=>navigate(-1)}>← Back to discovery</button><section className="anime-detail-hero" style={anime.bannerImage?{backgroundImage:'linear-gradient(90deg,#070b16f5 0%,#070b16c9 48%,#070b1680 100%),url('+anime.bannerImage+')'}:undefined}><div className="detail-cover"><img src={anime.coverImage?.extraLarge} alt={title+' poster'}/></div><div className="detail-heading"><span className="eyebrow">{[anime.format,anime.seasonYear,anime.status].filter(Boolean).join(' · ')}</span><h1>{title}</h1>{anime.title?.native&&<p className="detail-native">{anime.title.native}</p>}<div className="detail-meta"><span>★ {anime.averageScore?Math.round(anime.averageScore/10)+'/10':'Not rated'}</span><span>{anime.episodes||'—'} episodes</span><span>{anime.duration||'—'} min / episode</span></div><div className="detail-genres">{(anime.genres||[]).map(g=><span key={g}>{g}</span>)}</div><button className="primary" onClick={()=>toggleSave(title)}>{saved.includes(title)?'Saved to watchlist':'Add to watchlist'} <Plus size={15}/></button></div></section><section className="detail-trailer detail-trailer-below"><div className="detail-trailer-heading"><span className="eyebrow">THE FIRST LOOK</span><h2>Step into the story.</h2><p>Watch the official preview, when one is available.</p></div>{trailer?(showTrailer?<iframe src={trailer+'?autoplay=1&rel=0'} title={title+' trailer'} allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowFullScreen/>:<button className="detail-trailer-poster" onClick={()=>setShowTrailer(true)} style={anime.trailer.thumbnail?{backgroundImage:'linear-gradient(#07101a22,#07101a88),url('+anime.trailer.thumbnail+')'}:undefined}><Play size={32}/><b>Play official trailer</b></button>):<div className="detail-no-trailer">An official trailer isn't available for this title yet.</div>}</section><section className="detail-content-grid"><article className="detail-about"><span className="eyebrow">THE STORY</span><h2>About {title}</h2><p>{about||'No synopsis is available yet.'}</p>{anime.studios?.nodes?.length>0&&<p className="detail-studio">Animation studio: {anime.studios.nodes.map(x=>x.name).join(', ')}</p>}</article><aside className="detail-watch"><span className="eyebrow">WATCH INFORMATION</span><h2>Viewing details</h2><p>Straw Hat is a discovery and community experience. Episodes are not hosted here. Check the official release and licensed availability in your region.</p><div className="detail-viewing-facts"><span>Release status <b>{anime.status||'Not listed'}</b></span><span>Format <b>{anime.format||'Not listed'}</b></span><span>Season <b>{anime.seasonYear||'Not listed'}</b></span></div></aside></section></div>
