 const load=async()=>{if(!isAdmin||!supabase)return;const{data,error}=await supabase.from('media_assets').select('id,title,media_type,storage_path,mime_type,file_size_bytes,is_published,placement,created_at').order('created_at',{ascending:false}).limit(150);if(error)notify('Could not load media: '+error.message);else setAssets(data||[])};
