 {section==='overview'&&<><div className="admin-welcome"><div><span className="eyebrow">WELCOME BACK, CAPTAIN</span><h2>Keep the studio <em>sailing.</em></h2><p>Manage home artwork, page banners, feature imagery and loop video with live previews and controlled publishing.</p></div><button className="primary" onClick={()=>setSection('upload')}>Upload new media <Plus size={16}/></button></div><div className="admin-metrics"><article><span>ALL ASSETS</span><b>{assets.length}</b><small>Stored in the media library</small></article><article><span>PUBLISHED</span><b>{published}</b><small>Currently marked live</small></article><article><span>IMAGES</span><b>{images}</b><small>Visual assets</small></article><article><span>VIDEOS</span><b>{videos}</b><small>Loop and motion assets</small></article></div><section className="admin-panel"><span className="eyebrow">HOME PAGE IMAGE SLOTS</span><h2>Artwork placements</h2><div className="admin-slot-grid">{slots.map(([id,label])=><button key={id} onClick={()=>{setSlot(id);setSelectedFile(null);setSection('upload')}}><span>{label}</span><small>{assets.filter(a=>a.placement?.slot===id&&a.is_published).length?'LIVE ARTWORK':'NO LIVE ARTWORK'}</small><ArrowUpRight/></button>)}</div></section><div className="admin-home-grid"><section className="admin-panel"><span className="eyebrow">QUICK ACTIONS</span><h2>Studio actions</h2><button onClick={()=>setSection('upload')}><Plus/><span><b>Upload and crop artwork</b><small>Preview image position before publishing</small></span><ArrowUpRight/></button><button onClick={()=>setSection('media')}><MonitorPlay/><span><b>Manage all media</b><small>Publish, unpublish and inspect assets</small></span><ArrowUpRight/></button></section><section className="admin-panel"><span className="eyebrow">PUBLISHING CHECKLIST</span><h2>Quality control</h2><ul><li>Use 16:9 landscape artwork for home feature slots.</li><li>Check focal point on phone and desktop.</li><li>Keep source files and use high-resolution originals.</li><li>Publish only artwork you have permission to use.</li></ul></section></div></>}
